  '%10 = virgülü bir sola kaydır, %1 = iki sola. %5 = %10\'un yarısı.\n240\'ın %15\'i → 24 + 12 = 36.\nYer değiştirme serbest: 25\'in %8\'i = 8\'in %25\'i = 2.': '10% = move the decimal point one place left, 1% = two places. 5% = half of 10%.\n15% of 240 → 24 + 12 = 36.\nYou can swap them: 8% of 25 = 25% of 8 = 2.',
  '%30 indirim = fiyatın %70\'ini öde: 450 × 0,7 = 315.\nArt arda indirimler toplanmaz, çarpılır: %20 sonra %10 → 0,8 × 0,9 = 0,72 → toplam %28.\nEtiket fiyatı: 336 TL %30 indirimliyse 336 ÷ 0,7 = 480.': '30% off = pay 70% of the price: 450 × 0,7 = 315.\nSuccessive discounts multiply, they don\'t add: 20% then 10% → 0,8 × 0,9 = 0,72 → 28% in total.\nTag price: if 336 TL is 30% off, 336 ÷ 0,7 = 480.',
  '(sol üst − sağ alt) × (sağ üst + sol alt)': '(top left − bottom right) × (top right + bottom left)',
