  '2 ve 5 → son basamağın kalanı; 4 → son iki basamak; 8 → son üç basamak.\n3 ve 9 → rakamlar toplamının kalanı. 7452 ÷ 9 → 7+4+5+2 = 18 → kalan 0.\n11 → sağdan +, −, + … sırayla topla: 8316 → 6 − 1 + 3 − 8 = 0 → kalan 0.\n6 → 3\'e göre kalan r; sayının tek/çift oluşuna uyan r ya da r+3.': '2 and 5 → remainder of the last digit; 4 → last two digits; 8 → last three digits.\n3 and 9 → remainder of the digit sum. 7452 ÷ 9 → 7+4+5+2 = 18 → remainder 0.\n11 → alternate +, −, + … from the right: 8316 → 6 − 1 + 3 − 8 = 0 → remainder 0.\n6 → remainder r mod 3; then r or r+3, whichever matches the number being odd or even.',
