  '25 = 100 ÷ 4. Sayıyı 100\'le çarp, 4\'e böl.\n36 × 25 → 3600 ÷ 4 = 900.\nÖnce 4\'e bölmek kolaysa böl: 84 × 25 → 21 × 100 = 2100.\n÷25 için: 4 ile çarp, 100\'e böl: 1300 ÷ 25 → 5200 ÷ 100 = 52.\n×75 = ×300 ÷ 4, ×125 = ×1000 ÷ 8.': '25 = 100 ÷ 4. Multiply by 100, divide by 4.\n36 × 25 → 3600 ÷ 4 = 900.\nIf dividing by 4 first is easier, do that: 84 × 25 → 21 × 100 = 2100.\nFor ÷25: multiply by 4, divide by 100: 1300 ÷ 25 → 5200 ÷ 100 = 52.\n×75 = ×300 ÷ 4, ×125 = ×1000 ÷ 8.',
