  'Bir çarpanı yarıla, ötekini ikiyle çarp: çarpım değişmez.\n16 × 35 → 8 × 70 = 560.\n125 × 48 → 250 × 24 → 500 × 12 = 6000.\n3,5 × 16 → 7 × 8 = 56.': 'Halve one factor and double the other: the product stays the same.\n16 × 35 → 8 × 70 = 560.\n125 × 48 → 250 × 24 → 500 × 12 = 6000.\n3,5 × 16 → 7 × 8 = 56.',
