  'Bölen': 'Divisor',
  'Bölen solda, bölünen sağda hazır. Bölümün birler basamağı işaretli çubuğa gelir.\nKural: bölen, bölünenin ilk basamağına sığıyorsa bölüm basamağını iki çubuk sola, sığmıyorsa bir çubuk sola yaz. Sonra bölüm × bölen\'i, bölüm basamağının hemen sağındaki iki çubuktan çıkar.\n84 ÷ 4: 8\'e 4 sığar » 2\'yi iki sola yaz, 08 çıkar; 4\'e 4 sığar » 1\'i iki sola yaz, 04 çıkar. Bölüm 21, bölünen sıfırlandı.': 'The divisor is ready on the left, the dividend on the right. The quotient’s ones digit goes on the marked rod.\nRule: if the divisor fits into the dividend’s first digit, write the quotient digit two rods to the left; if not, one rod to the left. Then subtract quotient × divisor from the two rods just right of the quotient digit.\n84 ÷ 4: 4 fits into 8 » write 2 two rods left, subtract 08; 4 fits into 4 » write 1 two rods left, subtract 04. Quotient 21, dividend cleared.',
