  'Bu bölümde abaküs sana bir sayı gösteriyor, sen yazıyorsun.\nHer çubuğu tek bakışta oku: beşlik inmişse 5, üstüne kirişe değen birlikler.\nSoldan sağa oku; boş çubuk 0 demektir. Sayma, şekli tanı.': 'In this level the abacus shows you a number and you type it.\nRead each rod at a glance: 5 if the five-bead is down, plus the one-beads touching the beam.\nRead left to right; an empty rod means 0. Don’t count, recognize the shape.',
