  'Çarp': 'Multiply',
  'Çarpılan': 'Multiplicand',
  'Çarpılan solda hazır, çarpan soruda. Çarpım sağdaki alana kurulur; birler basamağı en sağ çubuktadır.\nÇarpım en fazla (çarpılan + çarpan) basamak sayısı kadar çubuk tutar: 34 × 6 » 3 çubuk.\nBasamakları soldan sağa çarp, her ara çarpımı iki basamaklı yaz (gerekirse başa 0): 3 × 6 = 18 » sağdan 3. ve 2. çubuk; 4 × 6 = 24 » sağdan 2. ve 1. çubuk. Sonuç 204.': 'The multiplicand is ready on the left, the multiplier is in the question. The product goes in the right-hand area; its ones digit is on the rightmost rod.\nThe product takes at most as many rods as the digits of multiplicand + multiplier: 34 × 6 » 3 rods.\nMultiply digits left to right and write each partial product as two digits (with a leading 0 if needed): 3 × 6 = 18 » rods 3 and 2 from the right; 4 × 6 = 24 » rods 2 and 1 from the right. Result 204.',
