  'Çıkar': 'Subtract',
  'Çıkaracak kadar boncuk yoksa soldaki çubuktan 1 ödünç al (−10), burada tümleyeni ekle.\n−9: soldakinden 1 indir, burada 1 kaldır. 12 − 9 » 3.\n−8: soldakinden 1 indir, burada 2 kaldır. 13 − 8 » 5.': 'If there aren’t enough beads to take away, borrow 1 from the rod on the left (−10) and add the complement here.\n−9: lower 1 on the left, raise 1 here. 12 − 9 » 3.\n−8: lower 1 on the left, raise 2 here. 13 − 8 » 5.',
  'Çıkarılacak birlikler kirişte yoksa beşliği kaldır, tümleyeni ekle.\n−4: beşliği kaldır, 1 birlik kaldır. 6 − 4 » 2.\n−3: beşliği kaldır, 2 birlik kaldır. 7 − 3 » 4.': 'If the one-beads to take away aren’t on the beam, raise the five-bead and add the complement.\n−4: raise the five-bead, raise 1 one-bead. 6 − 4 » 2.\n−3: raise the five-bead, raise 2 one-beads. 7 − 3 » 4.',
  'Çıkarma': 'Subtraction',
  'Çıkarmada boncukları kirişten uzaklaştır.\n8 − 3 » 3 birlik indir. 9 − 6 » beşliği kaldır, 1 birlik indir.\nAra sonuç her adımda tahtada; geri dönüp hesaplama.': 'To subtract, move beads away from the beam.\n8 − 3 » lower 3 one-beads. 9 − 6 » raise the five-bead, lower 1 one-bead.\nThe running result is on the board at every step; don’t go back and recalculate.',
  'Çıkarmak yerine kasiyer gibi yukarı say.\n100 − 47,35: 47,35 → 48 (0,65) → 50 (2) → 100 (50).\nToplam 0,65 + 2 + 50 = 52,65.': 'Instead of subtracting, count up like a cashier.\n100 − 47,35: 47,35 → 48 (0,65) → 50 (2) → 100 (50).\nTotal 0,65 + 2 + 50 = 52,65.',
