  'Değişim = fark ÷ eski değer.\n80 → 100: fark 20, 20 ÷ 80 = %25 artış.\nAzalış eksi yazılır: 120 → 90 = −25.\nArt arda +%20 ve −%20: 1,2 × 0,8 = 0,96 → net −4.': 'Change = difference ÷ old value.\n80 → 100: difference 20, 20 ÷ 80 = a 25% increase.\nA decrease is written as negative: 120 → 90 = −25.\n+20% then −20%: 1,2 × 0,8 = 0,96 → net −4.',
