  'Eklenecek birlikler boşta yoksa beşliği kullan: 5\'in tümleyeni (küçük arkadaş).\n+4: beşliği indir, 1 birlik indir. 3 + 4 » 7.\n+3: beşliği indir, 2 birlik indir. 4 + 3 » 7.\nÇiftler: 4 ile 1, 3 ile 2. İlk iki soruda oklar yol gösterir.': 'If there aren’t enough free one-beads to add, use the five-bead: the complement of 5 (small friend).\n+4: lower the five-bead, lower 1 one-bead. 3 + 4 » 7.\n+3: lower the five-bead, lower 2 one-beads. 4 + 3 » 7.\nPairs: 4 and 1, 3 and 2. In the first two questions arrows show the way.',
