  'Ezber hız kazandırır: 2¹⁰ = 1024, 2¹⁶ = 65536.\nKomşu kareden git: (n+1)² = n² + 2n + 1.\n24² = 576 ise 25² = 576 + 49 = 625.\nKarekök için son rakama ve büyüklüğe bak: √729 → 27² = 729.': 'Memorizing makes you fast: 2¹⁰ = 1024, 2¹⁶ = 65536.\nStep from a neighboring square: (n+1)² = n² + 2n + 1.\nIf 24² = 576, then 25² = 576 + 49 = 625.\nFor square roots, look at the last digit and the size: √729 → 27² = 729.',
