  'Her basamak kendi çubuğunda, soldan sağa: 352 + 146 » yüzlere 1, onlara 4, birlere 6.\nGözünü sayının tamamında değil sıradaki basamakta tut.': 'Each digit on its own rod, left to right: 352 + 146 » 1 to the hundreds, 4 to the tens, 6 to the ones.\nKeep your eyes on the next digit, not the whole number.',
  'Her çubuk 0–9 arası olmalı': 'Each rod must be 0–9',
  'Her çubuk kendi kararını verir. 34 + 23 » onlarda +2 = +5 − 3, birlerde +3 = +5 − 2 » 57.\nSoldan sağa: önce onlar, sonra birler.': 'Each rod makes its own decision. 34 + 23 » tens +2 = +5 − 3, ones +3 = +5 − 2 » 57.\nLeft to right: tens first, then ones.',
  'Her çubukta kirişin üstünde 1 beşlik, altında 4 birlik boncuk var. Sadece kirişe değen boncuklar sayılır.\n7 = beşlik + 2 birlik. Hiçbir boncuk kirişte değilse çubuk 0\'dır.\nEn sağ çubuk birler, solundaki onlar, sonra yüzler.\nBirlikleri başparmakla yukarı it, işaret parmağıyla aşağı indir; beşliği işaret parmağıyla indir ve kaldır. Boncuğu kaydırabilir ya da dokunabilirsin.\nSayıyı kur, sonra Tamam\'a dokun.': 'Each rod has 1 five-bead above the beam and 4 one-beads below it. Only beads touching the beam count.\n7 = five-bead + 2 one-beads. If no bead touches the beam, the rod is 0.\nThe rightmost rod is the ones, the one to its left the tens, then the hundreds.\nPush one-beads up with your thumb and down with your index finger; move the five-bead down and up with your index finger. You can slide or tap a bead.\nSet the number, then tap OK.',
  'Her karede üst + alt = sol + sağ.': 'In each square top + bottom = left + right.',
  'Her karede üst × alt = sol × sağ.': 'In each square top × bottom = left × right.',
  'Her karede üst × alt, sol ve sağ rakam yan yana yazılınca çıkan sayı (7 × 8 = 56 ise sol 5, sağ 6).': 'In each square top × bottom is the number made by writing the left and right digits side by side (7 × 8 = 56 means left 5, right 6).',
  'Her karenin ortasındaki sayı köşelerden aynı kuralla çıkıyor. Soru işareti hangi sayı?': 'The number in the middle of each square comes from its corners by the same rule. Which number is the question mark?',
  'her rakamından 1 çıkarılmış hâli': 'version with 1 taken from each digit',
  'her rakamının karesi yan yana yazılmış hâli': 'digit squares written side by side',
  'Her satır a, b, c = sonuç biçiminde aynı kuralı izliyor. Son sonuç ne?': 'Each row follows the same rule in the form a, b, c = result. What is the last result?',
  'Her satır ve sütunda eşit güneş ve ay · üç aynı yan yana gelmez': 'Equal suns and moons in every row and column · no three alike in a row',
  'Her satırda aynı kural var. Soru işaretinin yerine hangi sayı gelmeli?': 'Each row follows the same rule. Which number replaces the question mark?',
  'Her satırda boyut aynı kalıyor.': 'In each row the size stays the same.',
  'Her satırda çizgiler aynı kalıyor.': 'In each row the lines stays the same.',
  'Her satırda dolgu aynı kalıyor.': 'In each row the fill stays the same.',
  'Her satırda şekil aynı kalıyor.': 'In each row the shape stays the same.',
  'Her satırda şekil sayısı aynı kalıyor.': 'In each row the number of shapes stays the same.',
  'Her satırda üçüncü hücre, ilk iki hücreden yalnızca birinde olan çizgileri gösterir; ortak çizgiler silinir.': 'In each row the third cell shows the lines that are in only one of the first two; shared lines disappear.',
  'Her satırda üçüncü hücre, ilk iki hücrenin bütün çizgilerini birleştirir.': 'In each row the third cell combines all lines of the first two.',
  'Her satırda üçüncü hücrede yalnızca ilk iki hücrenin ortak çizgileri kalır.': 'In each row the third cell keeps only the lines the first two share.',
  'Her satırda üçüncü hücredeki şekil sayısı ilk ikisinin toplamı.': 'In each row the third cell has as many shapes as the first two together.',
  'Her sayı aynı kuralla dönüşüyor. Son sayı neye dönüşür?': 'Each number changes by the same rule. What does the last number become?',
  'Her şekil bir sayı. Son satırın sonucu ne?': 'Each shape is a number. What is the result of the last row?',
  'Her sütunda boyut aynı kalıyor.': 'In each column the size stays the same.',
  'Her sütunda çizgiler aynı kalıyor.': 'In each column the lines stays the same.',
  'Her sütunda dolgu aynı kalıyor.': 'In each column the fill stays the same.',
  'Her sütunda şekil aynı kalıyor.': 'In each column the shape stays the same.',
  'Her sütunda şekil sayısı aynı kalıyor.': 'In each column the number of shapes stays the same.',
  'Her sütunda üçüncü hücre, ilk iki hücreden yalnızca birinde olan çizgileri gösterir; ortak çizgiler silinir.': 'In each column the third cell shows the lines that are in only one of the first two; shared lines disappear.',
  'Her sütunda üçüncü hücre, ilk iki hücrenin bütün çizgilerini birleştirir.': 'In each column the third cell combines all lines of the first two.',
  'Her sütunda üçüncü hücrede yalnızca ilk iki hücrenin ortak çizgileri kalır.': 'In each column the third cell keeps only the lines the first two share.',
  'Her sütunda üçüncü hücredeki şekil sayısı ilk ikisinin toplamı.': 'In each column the third cell has as many shapes as the first two together.',
  'Her taş, altındaki iki taştan aynı kuralla çıkıyor. Soru işareti hangi sayı?': 'Each stone comes from the two below it by the same rule. Which number is the question mark?',
  'Her taş, altındaki iki taştan aynı kuralla çıkıyor. Tepede hangi sayı olmalı?': 'Each stone comes from the two below it by the same rule. Which number goes at the top?',
  'Her ters üçgende üstteki iki sayı alttakini aynı kuralla veriyor. Soru işareti hangi sayı?': 'In each upside-down triangle the two top numbers give the bottom one by the same rule. Which number is the question mark?',
