  'İki': 'Two',
  'İki basamaklı sayılar': 'Two-digit numbers',
  'İki basamaklı sayılar ve dört karar: doğrudan, 5\'in tümleyeni, 10\'un tümleyeni, karışık.\nHer basamakta kararı bir bakışta ver; kaç ettiğini hesaplama, boncuk şekline bak.': 'Two-digit numbers and four decisions: direct, complement of 5, complement of 10, mixed.\nDecide at a glance for each digit; don’t work out the value, look at the bead shape.',
  'İki basamaklı sayılar, artı ve eksi. Ritmini bul: göz, el, sonraki sayı.': 'Two-digit numbers, plus and minus. Find your rhythm: eye, hand, next number.',
  'İki basamaklı sayılar: iki hamle, önce onlar, sonra birler. Sayıyı bütün olarak fotoğrafla.': 'Two-digit numbers: two moves, tens first, then ones. Take in the number as a whole picture.',
  'İki basamaklı sayıyı 11\'le çarparken rakamları ayır, araya toplamlarını yaz.\n36 × 11 → 3 | 3+6 | 6 = 396.\nToplam 10 veya fazlaysa eldeyi soldakine ekle: 78 × 11 → 7 | 15 | 8 → 858.\nÜç basamakta komşuları topla: 243 × 11 → 2 | 6 | 7 | 3 = 2673.': 'To multiply a two-digit number by 11, split the digits and write their sum in between.\n36 × 11 → 3 | 3+6 | 6 = 396.\nIf the sum is 10 or more, carry 1 to the left: 78 × 11 → 7 | 15 | 8 → 858.\nWith three digits, add neighbors: 243 × 11 → 2 | 6 | 7 | 3 = 2673.',
  'İki ipli uçurtma': 'Two-string kite',
  'İki kapı': 'Two gates',
  'İki kibrit çöpünün yerini değiştirerek eşitliği doğru yap (= işareti sabit). Hangisi elde edilir?': 'Move two matchsticks to make the equation true (the = sign stays). Which do you get?',
  'İki liste: önce ilk listeyi yerleştirip hatırla, sonra sarayı temizle ve ikinci listeyi aynı duraklara koy.': 'Two lists: place and recall the first list, then clear the palace and put the second list on the same stops.',
  'İki renk': 'Two colors',
  'İki sayı da 100\'e yakınsa eksiklerini bul.\n97 × 94: eksikler 3 ve 6. Çapraz çıkar: 97 − 6 = 91. Eksikleri çarp: 3 × 6 = 18 → 9118.\nÇarpım tek basamaklıysa başına 0 koy: 98 × 97 → 95 | 06 = 9506.\n100\'ün üstünde fazlaları ekle: 103 × 107 → 110 | 21 = 11021.': 'If both numbers are near 100, find how far each falls short.\n97 × 94: shortfalls 3 and 6. Cross-subtract: 97 − 6 = 91. Multiply the shortfalls: 3 × 6 = 18 → 9118.\nIf that product is one digit, pad it with 0: 98 × 97 → 95 | 06 = 9506.\nAbove 100, add the excesses: 103 × 107 → 110 | 21 = 11021.',
  'İki sayı yuvarlak bir sayıya eşit uzaklıktaysa (a − b)(a + b) = a² − b² kullan.\n47 × 53 = 50² − 3² = 2500 − 9 = 2491.\n23 × 27 = 25² − 2² = 625 − 4 = 621.': 'If two numbers are equally far from a round number, use (a − b)(a + b) = a² − b².\n47 × 53 = 50² − 3² = 2500 − 9 = 2491.\n23 × 27 = 25² − 2² = 625 − 4 = 621.',
