  'İlk denemede, hatasız tamamlandı.': 'Done on the first try, without mistakes.',
  'İlk sayı tahtada hazır; aşağıdaki sayıları sırayla ekle.\nDoğrudan hamle: gereken boncuklar boşta duruyorsa onları kirişe getir. 12 + 6 » birlerde beşlik + 1 birlik.\nSon sonucu tahtada bırak ve Tamam\'a dokun.': 'The first number is already on the board; add the numbers below in order.\nDirect move: if the beads you need are free, bring them to the beam. 12 + 6 » five-bead + 1 one-bead on the ones.\nLeave the final result on the board and tap OK.',
