  'Kâğıt katlama': 'Paper folding',
  'Kâğıttaki gibi sağdan değil, büyük basamaklardan başla ve ara toplamı akılda tut.\n487 + 356 → 400 + 300 = 700 → 780 + 50 = 830 → 837 + 6 = 843.\nSöylediğin ilk sayı zaten cevabın büyük kısmıdır.': 'Unlike on paper, start from the big digits, not the right, and keep the running total in mind.\n487 + 356 → 400 + 300 = 700 → 780 + 50 = 830 → 837 + 6 = 843.\nThe first number you say is already most of the answer.',
