  'KDV eklemek = 1,2 ile çarpmak: 250 → 300.\nKDV dahil fiyattan hariç fiyata 1,2\'ye bölerek dön (%20 çıkarmak yanlış!): 360 → 300.\nİçindeki KDV = dahil fiyatın 1/6\'sı: 360 → 60.\nBahşiş %15 = %10 + yarısı: 340 → 34 + 17 = 51.': 'Adding VAT = multiplying by 1,2: 250 → 300.\nFrom a price with VAT back to one without: divide by 1,2 (taking off 20% is wrong!): 360 → 300.\nThe VAT inside = 1/6 of the price with VAT: 360 → 60.\nA 15% tip = 10% + half of it: 340 → 34 + 17 = 51.',
