  'Kurma sorularında abaküs dağınık başlıyor: önce temizle.\nParmağını kirişin üstünde soldan sağa kaydır ya da Sıfırla\'ya dokun. Gerçek sorobanda alt boncuklar abaküs hafif eğilerek indirilir, sonra işaret parmağı kiriş boyunca kayıp beşlikleri kaldırır.\nAradaki okuma sorularında sayıyı yaz.': 'In setting questions the abacus starts messy: clear it first.\nSlide your finger left to right along the beam or tap Reset. On a real soroban you tilt it slightly to drop the lower beads, then run your index finger along the beam to raise the five-beads.\nIn the reading questions in between, type the number.',
