  'Ödünçten sonra tümleyeni ekleyecek boncuk yoksa 5\'in tümleyeniyle ekle: +4 = +5 − 1.\n−6 = −10 + 5 − 1, −7 = −10 + 5 − 2, −8 = −10 + 5 − 3, −9 = −10 + 5 − 4.\n14 − 6 » onlardan 1 indir, beşliği indir, 1 birlik indir » 8.': 'If after borrowing there aren’t beads to add the complement, add it with the complement of 5: +4 = +5 − 1.\n−6 = −10 + 5 − 1, −7 = −10 + 5 − 2, −8 = −10 + 5 − 3, −9 = −10 + 5 − 4.\n14 − 6 » lower 1 from the tens, lower the five-bead, lower 1 one-bead » 8.',
