  'Önce bölüm basamağını tahmin et: 672 ÷ 32 » 6\'da 3 iki kez » 2.\nKural aynı: 32, 67\'ye sığıyor » iki sola. Sonra 2 × 3 = 06 ve 2 × 2 = 04\'ü birer çubuk kayarak çıkar.\nTahmin büyük geldiyse çıkarma yetmez: bölüm basamağını 1 azalt, bir bölen geri ekle.': 'Estimate the quotient digit first: 672 ÷ 32 » 3 goes into 6 twice » 2.\nSame rule: 32 fits into 67 » two to the left. Then subtract 2 × 3 = 06 and 2 × 2 = 04, shifting one rod each time.\nIf the estimate was too big, the subtraction won’t work: lower the quotient digit by 1 and add one divisor back.',
