  'Sayılar rakamlarıyla oynanarak dönüşüyor. Son sayının karşılığı ne?': 'The numbers change by playing with their digits. What does the last one map to?',
  'Sayılar tek tek geçer; zihindeki boncuklar her sayıda kıpırdasın. İçinden sayı okuma, hareketi gör.': 'Numbers pass one by one; let the beads in your mind move with each one. Don’t read the numbers to yourself, see the movement.',
  'Sayılar tek tek, kısa süre görünür. Gördüğün anda abaküse ekle; sayıyı aklında biriktirme.\nSon sayıdan sonra sonucu tahtada bırak ve Tamam\'a dokun.': 'Numbers appear one by one, briefly. Add each to the abacus as soon as you see it; don’t pile them up in your head.\nAfter the last number, leave the result on the board and tap OK.',
  'Sayıları izle, abaküste topla': 'Watch the numbers, add them on the abacus',
  'Sayıları izle, zihninde topla': 'Watch the numbers, add them in your head',
  'Sayıyı abaküse kur': 'Set the number on the abacus',
  'Sayıyı bul': 'Find the number',
  'Sayıyı soldan sağa kur: önce yüzler, sonra onlar, sonra birler.\nSıfır olan basamağın çubuğuna dokunma: 405\'te onlar çubuğu boş kalır.\nBoncuk şekline alış: 6 = beşlik + 1, 9 = beşlik + 4. Saymak yerine şekli tanı.': 'Set the number left to right: hundreds first, then tens, then ones.\nLeave the rod of a zero digit alone: in 405 the tens rod stays empty.\nGet used to bead shapes: 6 = five-bead + 1, 9 = five-bead + 4. Recognize the shape instead of counting.',
  'Sehpa': 'Coffee table',
