  'solda': 'on the left',
  'Soldaki çubuk 9 ise +10 orada da taşar: 97 + 5 » yüzlere 1, onlardan 9 çıkar, birlerden 5 çıkar » 102.\nÖdünçte tersi: 103 − 5 » yüzlerden 1 indir, onlarda 9 kur, birlerde beşliği indir » 98.\nElde ya da ödünç, boş olmayan bir çubuk bulana kadar sola zincirlenir.': 'If the rod on the left is 9, the +10 overflows there too: 97 + 5 » 1 to the hundreds, take 9 from the tens, take 5 from the ones » 102.\nBorrowing is the reverse: 103 − 5 » lower 1 from the hundreds, set 9 on the tens, lower the five-bead on the ones » 98.\nA carry or borrow chains to the left until it finds a rod that isn’t empty.',
