  'Temel eleme: tacın çevresindeki sekiz hücreye ve taçları tamamlanmış satır, sütun ve bölgelerin kalan hücrelerine taç gelemez': 'Basic elimination: no crown can go in the eight cells around a crown or in the rest of a row, column or region that has all its crowns',
  'Temel taşları ezberle: 1/8 = 0,125 = %12,5 · 1/16 = 0,0625 · 1/20 = 0,05 · 1/25 = 0,04.\n3/8 = 3 × 0,125 = 0,375.\nPaydayı 100\'e tamamla: 7/20 = 35/100 = %35.': 'Memorize the building blocks: 1/8 = 0,125 = 12,5% · 1/16 = 0,0625 · 1/20 = 0,05 · 1/25 = 0,04.\n3/8 = 3 × 0,125 = 0,375.\nScale the denominator to 100: 7/20 = 35/100 = 35%.',
