  'Topla': 'Add',
  'Toplam 9\'u aşıyorsa 10\'un tümleyeni (büyük arkadaş): soldaki çubuğa 1 ekle, bu çubuktan tümleyeni çıkar.\n+9: soldakine +1, burada −1. 7 + 9 » 16.\n+8: soldakine +1, burada −2. 4 + 8 » 12.\nÇiftler: 9–1, 8–2, 7–3, 6–4, 5–5.': 'If the sum goes past 9, use the complement of 10 (big friend): add 1 to the rod on the left, take the complement away from this rod.\n+9: +1 on the left, −1 here. 7 + 9 » 16.\n+8: +1 on the left, −2 here. 4 + 8 » 12.\nPairs: 9–1, 8–2, 7–3, 6–4, 5–5.',
  'Toplama': 'Addition',
  'Toplama ve çıkarma karışık. Her adımda önce bak: boncuk boşta mı? Boştaysa doğrudan, değilse 5\'in tümleyeni.\nTümleyen çiftleri: 1–4, 2–3.': 'Addition and subtraction mixed. At each step look first: is the bead free? If so, direct; if not, the complement of 5.\nComplement pairs: 1–4, 2–3.',
