  '−2: beşliği kaldır, 3 birlik kaldır. 5 − 2 » 3.\n−1: beşliği kaldır, 4 birlik kaldır. 5 − 1 » 4.\nToplamada beşlik iner, birlik iner; çıkarmada beşlik kalkar, birlik kalkar.': '−2: raise the five-bead, raise 3 one-beads. 5 − 2 » 3.\n−1: raise the five-bead, raise 4 one-beads. 5 − 1 » 4.\nIn addition the five-bead goes down and one-beads go down; in subtraction the five-bead goes up and one-beads go up.',
