/// Lines with `{}` holes (Rust format holes, in order) or `{0}`, `{1}` … when English needs another order.
/// Most specific first: the first template that matches wins.
const List<(String, String)> enCoreTemplates = [
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. İki liste: önce ilk listeyi yerleştirip hatırla, sonra sarayı temizle ve ikinci listeyi aynı duraklara koy. Eşyayı seçeneklerden seçeceksin.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. Two lists: place and recall the first list, then clear the palace and put the second list on the same stops. You will pick the item from the options.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. İki liste: önce ilk listeyi yerleştirip hatırla, sonra sarayı temizle ve ikinci listeyi aynı duraklara koy. Eşyanın adını yazacaksın.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. Two lists: place and recall the first list, then clear the palace and put the second list on the same stops. You will type the item’s name.'),
  ('Katlamalar: {}. Kâğıt açılırken her katlama çizgisi bir ayna gibidir: delikler çizgiye göre yansır ve her açılışta sayıları ikiye katlanır. Kâğıtta {} delik açıldı, açılınca {} delik olur. Çapraz katlamada delik köşegene göre yansır.', 'Folds: {}. When the paper opens, each fold line acts like a mirror: holes are reflected across it and double with each unfold. {} holes were punched; unfolded there are {}. In a diagonal fold a hole reflects across the diagonal.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken duraklar karışık sorulacak: doğrudan o durağa ışınlan. Eşyayı seçeneklerden seçeceksin.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling the stops come in random order: jump straight to that stop. You will pick the item from the options.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken duraklar karışık sorulacak: doğrudan o durağa ışınlan. Eşyanın adını yazacaksın.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling the stops come in random order: jump straight to that stop. You will type the item’s name.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken sondan başa, geriye doğru yürüyeceksin. Eşyayı seçeneklerden seçeceksin.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling you walk backward, from the last stop to the first. You will pick the item from the options.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken kapıdan başlayıp sırayla yürüyeceksin. Eşyayı seçeneklerden seçeceksin.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling you walk in order, starting at the door. You will pick the item from the options.'),
  ('Katlamalar: {}. Kâğıt açılırken her katlama çizgisi bir ayna gibidir: delikler çizgiye göre yansır ve her açılışta sayıları ikiye katlanır. Kâğıtta {} delik açıldı, açılınca {} delik olur.', 'Folds: {}. When the paper opens, each fold line acts like a mirror: holes are reflected across it and double with each unfold. {} holes were punched; unfolded there are {}.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken sondan başa, geriye doğru yürüyeceksin. Eşyanın adını yazacaksın.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling you walk backward, from the last stop to the first. You will type the item’s name.'),
  ('{} sarayında {} durak. Her durağa bir eşya bırak: eşyayı durakla etkileşen canlı, tuhaf bir sahneye çevir. Hatırlarken kapıdan başlayıp sırayla yürüyeceksin. Eşyanın adını yazacaksın.', '{} palace: {} stops. Leave one item at each stop: turn it into a vivid, odd scene with the stop. When recalling you walk in order, starting at the door. You will type the item’s name.'),
  ('Doğru seçenek şeklin {}° saat yönünde döndürülmüş hâli. Ayna görüntüsü hangi açıyla döndürülürse döndürülsün üst üste gelmez; diğer seçeneklerde bir kare yer değiştirmiş.', 'The right option is the shape rotated {}° clockwise. A mirror image never matches however it is rotated; in the other options a square has moved.'),
  ('Katlayınca karşılıklı gelen yüzler: {}. Karşılıklı yüzler aynı anda görünemez. Yönü olan sembollerde, katlanınca okun ya da üçgenin hangi kenara baktığına da dikkat et. {}', 'Faces opposite each other when folded: {}. Opposite faces can\'t be seen together. For symbols with a direction, also check which edge the arrow or triangle points to when folded. {}'),
  ('{} birlikte hedef şekli tam olarak kaplar: toplam {} kare. Alanı tutan başka üçlüler de var ama onlar şekle yerleşmiyor; parçalar döndürülebilir, ters çevrilemez.', 'Together {} cover the target shape exactly: {} squares in all. Other triples have the right area but don\'t fit the shape; pieces can be rotated, not flipped.'),
  ('Elimde {} tane {} var, {} tane {} yığına benim koyduğum, {} tane {} oyun dışı, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', 'I have {} {}s, {} {}s in the pile are mine, {} {}s are out, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('Elinde {} tane {} var, {} tane {} yığına senin koyduğun, {} tane {} oyun dışı, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', 'You have {} {}s, {} {}s in the pile are yours, {} {}s are out, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('Bu yapıyı {}×{}×{} boyutunda dolu bir kutuya tamamlamak için kaç küp daha gerekir? (Her küp yere ya da başka bir küpün üstüne oturuyor; görünmeyen boşluk yok.)', 'How many more cubes are needed to complete this into a solid {}×{}×{} box? (Each cube sits on the floor or on another cube; no hidden gaps.)'),
  ('Sütun sütun say: her sütundaki küp sayısı en üstteki küpün yüksekliğine eşit. Toplam {} küp; bunların {} tanesi görünmüyor, sadece görünenleri saymak {} verir.', 'Count column by column: each column has as many cubes as its top cube is high. {} cubes in all; {} of them are hidden, counting only the visible ones gives {}.'),
  ('Zorlama zinciri: {} hücresine {} koyarsan tekli adımlar zinciri bir çelişkiye varıyor (bir hücreye ya da bir rakama yer kalmıyor); demek ki orada {} olamaz', 'Forcing chain: putting {1} in cell {0} leads through singles to a contradiction (a cell or a digit runs out of room); so {2} cannot go there'),
  ('XY-Wing: merkez {} ({}), kanatlar {} ({}) ve {} ({}); merkez hangi rakamı alırsa alsın kanatlardan biri {} olur, ikisini birden gören hücrelerden {} silinir', 'XY-Wing: pivot {} ({}), wings {} ({}) and {} ({}); whatever the pivot takes, one wing is {}, so remove {} from cells that see both'),
  ('Elimde {} tane {} var, {} tane {} yığına benim koyduğum, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', 'I have {} {}s, {} {}s in the pile are mine, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('Elinde {} tane {} var, {} tane {} yığına senin koyduğun, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', 'You have {} {}s, {} {}s in the pile are yours, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('{} tane {} yığına benim koyduğum, {} tane {} oyun dışı, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', '{} {}s in the pile are mine, {} {}s are out, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('{} tane {} yığına senin koyduğun, {} tane {} oyun dışı, {} tane {} açılan kartlardan başka elde; {} elinde en fazla {} tane {} olabilir, {} dedi → kesin Blöf!', '{} {}s in the pile are yours, {} {}s are out, {} {}s are in another hand (revealed); {} hand can hold at most {} {}s, yet {} were called → sure Bluff!'),
  ('Satır analizi — {}: daha {} güneş ve {} ay yerleşecek. Bunları üçlü oluşturmadan ve işaretleri bozmadan dizmenin her yolunda bu hücre {} oluyor.', 'Line analysis — {}: {} more suns and {} more moons to place. Every way to fit them without three in a row or breaking a sign makes this cell {}.'),
  ('X-Zinciri: {} için güçlü ve zayıf bağlar sırayla {} hücrelerini bağlıyor; iki uçtan biri mutlaka {}, ikisini birden gören hücrelerden {} silinir', 'X-Chain: for {}, alternating strong and weak links connect cells {}; one end must be {}, so remove {} from cells that see both'),
  ('XY-Zinciri: iki adaylı hücreler {} birbirini zorluyor; baş hücre {} değilse son hücre {} olur, ikisini birden gören hücrelerden {} silinir', 'XY-Chain: the two-candidate cells {} force each other; if the first cell is not {}, the last one is {}, so remove {} from cells that see both'),
  ('İşlem önceliği: önce çarpma ve bölme (soldan sağa), sonra toplama ve çıkarma. Sonuç {}; soldan sağa gidersen yanlışlıkla {} bulursun.', 'Order of operations: first multiplication and division (left to right), then addition and subtraction. Result {}; going left to right you would wrongly get {}.'),
  ('Bir saat her gün {} dakika geri kalıyor. Bugün doğru ayarlandı. En az kaç gün sonra yine doğru saati gösterir? (12 saatlik kadran)', 'A clock loses {} minutes every day. It was set right today. After how many days at least will it show the right time again? (12-hour dial)'),
