  ('Kapalı kart {}: krupiyede blackjack var, sigorta 2:1 kazanır. Temel strateji yine de \'alma\' der, çünkü normalde bunu bilemezsin.', 'Hole card {}: the dealer has blackjack, insurance pays 2:1. Basic strategy still says \'decline\', since normally you can\'t know this.'),
