  ('Adımları sırayla uygula: önce {}, sonra {}. Sıra önemlidir: ters sırada yapmak ya da bir adımı atlamak başka bir şekil verir.', 'Apply the steps in order: first {}, then {}. Order matters: doing them the other way round or skipping one gives another shape.'),
  ('Ayna alfabe: A ile Z, B ile Y, C ile V … her harf, alfabenin öbür ucundan aynı sıradaki harfle yer değiştiriyor. {} için {}.', 'Mirror alphabet: A with Z, B with Y, C with V … each letter swaps with the letter in the same place from the other end. {0} becomes {1}.'),
