  ('Deneme zinciri: {} hücresine taç koyup zorunlu hamleleri izlersen bir satır, sütun ya da bölge tıkanıyor; orası boş kalır', 'Trial chain: a crown in cell {} and the forced moves after it block a row, column or region; that cell stays empty'),
