  ('İki görünümden beş yüz ve yerleri belli olur; karşılıklı yüzler: {}. Doğru seçenek küpün başka bir yönden görünüşü. {}', 'The two views fix five faces and their places; opposite faces: {}. The right option is the cube seen from another side. {}'),
  ('{}: {} için iki güçlü bağ ({} = {} ve {} = {}) birbirini görüyor; {} ya da {} mutlaka {}, ikisini birden gören hücrelerden {} silinir', '{}: two strong links for {} ({} = {} and {} = {}) see each other; {} or {} must be {}, so remove {} from cells that see both'),
