  ('{}: {} {} hücreleri yalnız {} rakamlarını alabilir; bu {} rakam aynı birimdeki diğer hücrelerden silinir', '{0}: {1}, cells {2} can only hold {3}; remove these {4} digits from the other cells of the unit'),
  ('Uzun renginden küçük kart ({}): büyüklerini sonraya saklıyor, arkadakileri yükseltmeye zorluyor', 'Low card from the long suit ({}): saves the high ones and forces the next players to go higher'),
